'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const {fixture}=require('./fixture.cjs'),KEY='data-study-compiled-key',settle=()=>new Promise(r=>setImmediate(r));
function unknownNative(f){const required=new Set(f.profile.nodeBindings.map(n=>n.key));return [...f.doc.querySelectorAll('.examples-section li.example-card')].find(n=>!required.has(n.getAttribute(KEY))&&!n.hasAttribute(KEY));}
test('reviewer repro: append unkeyed native example rejects after MO and refresh',async()=>{const f=fixture('abolish');try{const list=f.doc.querySelector('.examples-section ol.examples');assert(list);const row=f.doc.createElement('li');row.className='example-card';row.innerHTML='<p class="example-text">new unmanaged source</p>';list.append(row);await settle();let refreshRejected=false;try{f.runtime.refresh()}catch(_){refreshRejected=true}assert.deepEqual({asyncInvalid:f.invalid()!==null,refreshRejected},{asyncInvalid:true,refreshRejected:true},'unknown native row must not bypass either boundary');assert(row.isConnected);}finally{f.close()}});
test('original unkeyed native row is baseline and removal is rejected',async()=>{const f=fixture('train');try{const original=unknownNative(f);assert(original,'actual replay has original unkeyed native rows');assert.equal(f.runtime.refresh(),true);original.remove();await settle();assert(f.invalid());assert.throws(()=>f.runtime.refresh(),/semantic/);assert.equal(original.isConnected,false);}finally{f.close()}});
test('replace entire semantic region or an outer ancestor cannot bypass observer',async()=>{for(const outer of [false,true]){const f=fixture('abolish');try{const region=f.doc.querySelector('.examples-section'),removed=outer?region.parentElement:region,replacement=removed.cloneNode(true);removed.replaceWith(replacement);await settle();assert(f.invalid());assert.throws(()=>f.runtime.refresh(),/semantic/);assert(replacement.isConnected);}finally{f.close()}}});
test('reorder original unkeyed rows or add unknown lazy is rejected without reconstruction',async()=>{for(const kind of ['reorder','lazy']){const f=fixture('train');try{const row=unknownNative(f);assert(row);let added;if(kind==='reorder')row.parentElement.append(row);else{added=f.doc.createElement('script');added.type='application/json';added.className='as-manifest';added.textContent='{"new":"unsupported"}';row.parentElement.append(added)}await settle();assert(f.invalid());assert.throws(()=>f.runtime.refresh(),/semantic|lazy/);if(added)assert(added.isConnected);}finally{f.close()}}});
test('original filters reader outer controls source script and footer changes remain legal',async()=>{for(const name of ['abolish','train']){const f=fixture(name);try{for(const button of f.doc.querySelectorAll('[data-sf-filter]'))f.fire('click',button);const control=f.doc.querySelector('.source-reader');for(const value of ['latex','full-paper']){control.value=value;control.dispatchEvent(new f.win.Event('change',{bubbles:true}));await settle();assert.equal(f.invalid(),null)}const label=control.closest('.source-reader-setting');assert(label);label.style.margin='1px';label.classList.add('tappable');label.hidden=false;const region=f.doc.querySelector('.examples-section'),script=f.doc.createElement('script');script.type='application/json';script.textContent='{"sourceOwned":true}';region.append(script);script.textContent='{"sourceOwned":"updated"}';script.remove();const footer=f.doc.createElement('footer');footer.textContent='source footer';f.doc.body.append(footer);footer.classList.add('current');await settle();assert.equal(f.invalid(),null);assert.equal(f.runtime.refresh(),true);}finally{f.close()}}});
